using WypozyczalniaSportowa.Domain.Contracts;
using WypozyczalniaSportowa.Domain.Pricing;
namespace WypozyczalniaSportowa.Domain; public sealed class Bicycle : SportEquipment, IReservable, IServiceable { private int _gears; public Bicycle(string n, decimal r, int gears) : base(n, r) => Gears = gears; internal Bicycle(int id, string n, decimal r, bool a, bool s, int g) : base(id, n, r, a, s) => Gears = g; public int Gears { get => _gears; private set => _gears = value < 1 ? throw new Exceptions.DomainValidationException("Rower musi mieć przełożenie.") : value; } public override string Kind => "Rower"; public override int Detail => Gears; public override decimal CalculateRentalPrice(RentalPeriod p, IPricingStrategy s) => s.Calculate(DailyRate, p); public override Equipment CloneEntity(bool deep) => new Bicycle(Id, Name, DailyRate, IsAvailable, NeedsService, Gears); public override string ToString() => $"{base.ToString()}, przełożenia: {Gears}"; }
